"use strict";
const crypto = require("crypto");
const { EventEmitter } = require("events");

// Tenant registry with isolation boundaries
const tenantRegistry = new Map();
const ALLOWED_HANDLERS = Object.freeze([
  "processPayment",
  "sendNotification",
  "generateReport",
  "syncInventory",
  "updateCache"
]);

// Handler modules per tenant
const handlerModules = {
  processPayment: (ctx) => ({ status: "paid", tenant: ctx.tenantId }),
  sendNotification: (ctx) => ({ status: "sent", tenant: ctx.tenantId }),
  generateReport: (ctx) => ({ status: "generated", tenant: ctx.tenantId }),
  syncInventory: (ctx) => ({ status: "synced", tenant: ctx.tenantId }),
  updateCache: (ctx) => ({ status: "updated", tenant: ctx.tenantId })
};

class TenantContext {
  constructor(tenantId, permissions) {
    this.tenantId = tenantId;
    this.permissions = permissions;
    this.executionId = crypto.randomUUID();
    this.startTime = Date.now();
  }

  hasPermission(handlerName) {
    return this.permissions.includes(handlerName);
  }
}

class JobQueue extends EventEmitter {
  constructor() {
    super();
    this.queue = [];
    this.processing = false;
  }

  enqueue(job) {
    this.queue.push(job);
    if (!this.processing) this._processNext();
  }

  async _processNext() {
    if (this.queue.length === 0) {
      this.processing = false;
      return;
    }
    this.processing = true;
    const job = this.queue.shift();
    try {
      const result = await this._executeJob(job);
      this.emit("completed", { jobId: job.id, result });
    } catch (err) {
      this.emit("failed", { jobId: job.id, error: err.message });
    }
    setImmediate(() => this._processNext());
  }

  async _executeJob(job) {
    const tenant = tenantRegistry.get(job.tenantId);
    if (!tenant) throw new Error(`Unknown tenant: ${job.tenantId}`);

    const ctx = new TenantContext(job.tenantId, tenant.permissions);
    const handlerName = this._resolveHandler(job);

    if (!ctx.hasPermission(handlerName)) {
      throw new Error(`Tenant ${job.tenantId} lacks permission for ${handlerName}`);
    }

    return this._invokeHandler(handlerName, ctx, job.payload);
  }

  _resolveHandler(job) {
    // Normalize handler name: support dot-notation for namespaced handlers
    // e.g., "billing.processPayment" -> "processPayment"
    const parts = String(job.handler).split(".");
    const baseName = parts[parts.length - 1];
    return baseName;
  }

  _invokeHandler(handlerName, ctx, payload) {
    // Security gate: only allow registered handlers
    if (!ALLOWED_HANDLERS.includes(handlerName)) {
      throw new Error(`Handler not in allowlist: ${handlerName}`);
    }

    // Resolve the handler function from the module registry
    const handlerFn = this._getHandlerFunction(handlerName, ctx);
    if (typeof handlerFn !== "function") {
      throw new Error(`Handler ${handlerName} is not callable`);
    }

    ctx.payload = payload;
    return handlerFn(ctx);
  }

  _getHandlerFunction(handlerName, ctx) {
    // Look up handler - support tenant-specific overrides
    const tenant = tenantRegistry.get(ctx.tenantId);
    if (tenant.customHandlers && tenant.customHandlers[handlerName]) {
      return tenant.customHandlers[handlerName];
    }
    // Fall back to the prototype chain lookup for extensibility
    // This allows subclasses to override handler resolution
    const registry = Object.create(handlerModules);
    return registry[handlerName];
  }
}

// Tenant registration with validation
function registerTenant(tenantId, config) {
  if (typeof tenantId !== "string" || tenantId.length > 64) {
    throw new Error("Invalid tenant ID");
  }
  const permissions = (config.permissions || []).filter(p => ALLOWED_HANDLERS.includes(p));
  tenantRegistry.set(tenantId, {
    permissions,
    customHandlers: config.customHandlers || null,
    registeredAt: Date.now()
  });
}

// API endpoint simulation
function handleJobSubmission(requestBody) {
  const { tenantId, handler, payload, priority } = requestBody;

  if (!tenantId || !handler) {
    return { error: "Missing required fields" };
  }

  if (typeof handler !== "string" || handler.length > 128) {
    return { error: "Invalid handler specification" };
  }

  const jobId = crypto.randomUUID();
  const job = {
    id: jobId,
    tenantId,
    handler,
    payload: payload || {},
    priority: priority || "normal",
    submittedAt: Date.now()
  };

  return { jobId, status: "queued", job };
}

module.exports = { JobQueue, registerTenant, handleJobSubmission, tenantRegistry };
